<script setup lang="ts">
import { ref } from "vue";
import { currentUser } from "../../state/auth";
import { logout } from "../../services/auth";
import { exportDeploymentBackup, inspectDeploymentBackup, restoreDeploymentBackup } from "../../services/exportImport";
import type { DeploymentBackupPreview } from "../../services/exportImport";
const password=ref(""),confirmPassword=ref(""),file=ref<File|null>(null),preview=ref<DeploymentBackupPreview|null>(null),selected=ref<string[]>([]);
const exporting=ref(false),processing=ref(false),error=ref<string|null>(null),message=ref<string|null>(null),sessionsRevoked=ref(false);
function validate(){if(password.value.length<12)throw new Error("Backup passwords must be at least 12 characters.");if(confirmPassword.value!==password.value)throw new Error("The backup passwords do not match.")}
async function exportBackup(){error.value=null;message.value=null;try{validate();exporting.value=true;const blob=await exportDeploymentBackup(password.value);const url=URL.createObjectURL(blob);const link=document.createElement("a");link.href=url;link.download=`archive-deployment-backup-${new Date().toISOString().replace(/[:.]/g,"-").slice(0,19)}.json`;link.click();URL.revokeObjectURL(url);password.value="";confirmPassword.value="";message.value="Encrypted deployment backup downloaded. Keep the backup and its password separate."}catch(err){error.value=err instanceof Error?err.message:"Failed to export deployment backup."}finally{exporting.value=false}}
function onFileSelected(e:Event){const input=e.target as HTMLInputElement;file.value=input.files?.[0]??null;preview.value=null;selected.value=[];error.value=null;message.value=null;}
async function decryptBackup(){error.value=null;message.value=null;if(!file.value){error.value="Choose an encrypted deployment backup first.";return}if(password.value.length<12){error.value="Enter the backup password (at least 12 characters).";return}processing.value=true;try{preview.value=await inspectDeploymentBackup(file.value,password.value);selected.value=preview.value.sections.filter(s=>s.available).map(s=>s.id)}catch(err){error.value=err instanceof Error?err.message:"Failed to decrypt deployment backup."}finally{processing.value=false}}
async function restore(){error.value=null;message.value=null;sessionsRevoked.value=false;if(!file.value||!selected.value.length){error.value="Choose the backup and at least one section to restore.";return}if(selected.value.includes("encryption")){if(!window.confirm("Restoring encryption keys will also replace the encrypted deployment settings that belong to those keys and invalidate all active sessions. Continue?"))return}processing.value=true;try{const result=await restoreDeploymentBackup(file.value,password.value,selected.value);message.value=result.message;sessionsRevoked.value=result.sessions_revoked;preview.value=null;if(result.sessions_revoked)password.value=""}catch(err){error.value=err instanceof Error?err.message:"Failed to restore deployment backup."}finally{processing.value=false}}
async function signOutNow(){currentUser.value=null;try{await logout()}catch{}window.location.assign("/login")}
</script>
<template><section class="section"><h2>Deployment backup</h2><p class="hint">Export or restore deployment settings, provider credentials, SMTP/OIDC secrets, and persistent Fernet keys. Users, sessions, libraries, media and other user data are never included.</p><div class="warning"><strong>Protect this file.</strong> The archive contains deployment secrets. Keep its password separate from the file.</div><div class="panel"><h3>Export</h3><form class="form" @submit.prevent="exportBackup"><label><span>Backup password</span><input v-model="password" type="password" minlength="12" maxlength="256" autocomplete="new-password" placeholder="At least 12 characters" required /></label><label><span>Confirm backup password</span><input v-model="confirmPassword" type="password" minlength="12" maxlength="256" autocomplete="new-password" required /></label><button type="submit" class="primary" :disabled="exporting">{{ exporting?"Encrypting…":"Export encrypted deployment backup" }}</button></form></div><div class="panel"><h3>Restore</h3><p class="hint">Upload the encrypted backup first. Then enter its password and decrypt it to review exactly which deployment sections are available before anything is replaced.</p><label class="upload"><span>{{ file?file.name:"Choose encrypted backup…" }}</span><input type="file" accept="application/json" @change="onFileSelected" /></label><label v-if="file"><span>Backup password</span><input v-model="password" type="password" minlength="12" maxlength="256" autocomplete="current-password" placeholder="At least 12 characters" /></label><button v-if="file&&!preview" type="button" class="secondary" :disabled="processing" @click="decryptBackup">{{ processing?"Decrypting…":"Decrypt and review backup" }}</button><div v-if="preview" class="restore-options"><h4>Choose what to replace</h4><label v-for="section in preview.sections" :key="section.id" class="option"><input v-model="selected" type="checkbox" :value="section.id" :disabled="!section.available" /><span><strong>{{ section.label }}</strong><small>{{ section.description }}</small></span></label><button type="button" class="primary" :disabled="processing||!selected.length" @click="restore">{{ processing?"Restoring…":"Restore selected settings" }}</button></div></div><div v-if="error" class="error">{{ error }}</div><div v-if="message" class="success">{{ message }}</div><div v-if="sessionsRevoked" class="session-warning"><strong>Your session was invalidated.</strong><p>The restore completed, but the server revoked active sessions because encryption keys were replaced. Nothing was signed you out automatically.</p><div><button type="button" class="primary" @click="signOutNow">Sign out now</button><button type="button" class="secondary" @click="window.location.reload()">Refresh page</button></div></div><div class="hint"><strong>Restore scope:</strong> this is a configuration/secret migration artifact, not a complete application backup. Keep your normal PostgreSQL and <code>/data</code> backups as well.</div></section></template>
<style scoped>.section{display:flex;flex-direction:column;gap:16px}.section h2{margin:0;color:#fff}.hint{color:#999;font-size:13px;line-height:1.5}.warning{background:rgba(214,138,52,.08);border:1px solid rgba(214,138,52,.28);border-radius:9px;padding:12px 14px;color:#c9c9c9;font-size:.8rem;line-height:1.5}.warning strong{color:#d68a34}.panel{border:1px solid #2f2f2f;border-radius:10px;padding:18px;background:#151515}.panel h3{margin:0 0 12px;color:#fff}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:end;max-width:760px}.form label,.panel>label{display:flex;flex-direction:column;gap:6px;color:#ccc;font-size:13px}.form input,.panel input{background:#111;border:1px solid #3a3a3a;border-radius:8px;color:#fff;padding:10px;font:inherit}.primary,.secondary{border:0;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.primary{background:#d68a34;color:#111}.secondary{background:rgba(255,255,255,.08);color:#fff}.primary:disabled,.secondary:disabled{opacity:.6;cursor:not-allowed}.upload{display:inline-flex!important;width:max-content;background:rgba(255,255,255,.08);padding:10px 14px;border-radius:8px;cursor:pointer;margin-bottom:12px}.upload input{display:none}.restore-options{margin-top:16px;border-top:1px solid #2a2a2a;padding-top:16px}.restore-options h4{margin:0 0 10px;color:#fff}.option{display:flex;gap:10px;align-items:flex-start;padding:11px;border:1px solid #333;border-radius:8px;background:#111;margin-bottom:8px;cursor:pointer}.option input{margin-top:3px}.option span{display:flex;flex-direction:column;gap:3px}.option small{color:#888;line-height:1.4}.error{color:#fca5a5;background:rgba(220,38,38,.1);border:1px solid rgba(220,38,38,.3);border-radius:8px;padding:8px 10px}.success{color:#86efac;background:rgba(34,197,94,.1);border:1px solid rgba(34,197,94,.3);border-radius:8px;padding:8px 10px}.session-warning{background:rgba(220,38,38,.1);border:1px solid rgba(220,38,38,.35);border-radius:10px;padding:14px;color:#fca5a5}.session-warning strong{color:#fff}.session-warning p{margin:6px 0 12px;line-height:1.5}.session-warning button+button{margin-left:8px}code{color:#ddd}@media(max-width:760px){.form{grid-template-columns:1fr}}
</style>